begin;
create table public.sp_cms_documents(slug text primary key,owner_id uuid not null references public.sp_owners(owner_id),draft jsonb not null,field_schema jsonb not null,version integer not null default 1,published_id uuid,updated_at timestamptz not null default now(),published_at timestamptz not null default now());
create index sp_cms_documents_owner on public.sp_cms_documents(owner_id);
create table public.sp_cms_revisions(id uuid primary key default gen_random_uuid(),slug text not null references public.sp_cms_documents(slug),owner_id uuid not null references public.sp_owners(owner_id),content jsonb not null,actor text not null,action text not null,created_at timestamptz not null default now());
create index sp_cms_revisions_slug on public.sp_cms_revisions(slug,created_at desc);
create index sp_cms_revisions_owner on public.sp_cms_revisions(owner_id);
alter table public.sp_cms_documents add constraint sp_cms_published foreign key(published_id) references public.sp_cms_revisions(id);
alter table public.sp_cms_documents enable row level security;
alter table public.sp_cms_revisions enable row level security;
revoke all on public.sp_cms_documents,public.sp_cms_revisions from public,anon,authenticated;
grant select on public.sp_cms_documents,public.sp_cms_revisions to authenticated;
create policy owner_read on public.sp_cms_documents for select to authenticated using(owner_id=(select auth.uid()) and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
create policy owner_read on public.sp_cms_revisions for select to authenticated using(owner_id=(select auth.uid()) and exists(select 1 from public.admin_users where user_id=(select auth.uid())));
insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('shared','675024a7-62f2-4eac-ba25-9718bb362e74','{"link_001":"/kansenscan","tekst_002":"Kansenscan","link_003":"/werkwijze","tekst_004":"Werkwijze","link_005":"/praktijkvoorbeelden","tekst_006":"Praktijkvoorbeelden","link_007":"/over","tekst_008":"Over Setpiece","tekst_009":"Tot 80%","tekst_010":"minder tijd nodig","tekst_011":"Bij opstellingen, trainingsvoorbereiding en spelersontwikkeling binnen Nankaro.","tekst_012":"Productontwikkeling en procesverbetering binnen voetbalclubs.","tekst_013":"Dagelijks","tekst_014":"sneller kunnen beslissen","tekst_015":"Markt- en verkoopinformatie kwam sneller beschikbaar voor beleidsbeslissers bij Cameranu.","tekst_016":"Analyse en samenvatting van terugkerende marktinformatie.","tekst_017":"Circa 70%","tekst_018":"tijdwinst in productie","tekst_019":"Nieuwsbriefproductie bij A.Vogel versnelde door website-inhoud geschikt te maken voor hergebruik.","tekst_020":"E-mailmarketing binnen de toegepaste werkwijze.","tekst_021":"Begrijpen","tekst_022":"Terugkerend verlies wordt zichtbaar.","tekst_023":"Bedrijfsdoel, werkproces en nulmeting concreet maken.","tekst_024":"Beslisser + proceseigenaar","tekst_025":"Kiezen","tekst_026":"De eerste haalbare prioriteit is onderbouwd.","tekst_027":"Maximaal drie processen vergelijken op waarde, risico en uitvoerbaarheid.","tekst_028":"Setpiece","tekst_029":"Werkend maken","tekst_030":"Eén kleine verbetering is in echt werk getest.","tekst_031":"De werkwijze inrichten, gebruiken en bijstellen met een medewerker.","tekst_032":"Medewerker + Setpiece","tekst_033":"Borgen","tekst_034":"De organisatie kan zelfstandig verder.","tekst_035":"Eigenaarschap, instructie, meting en vervolgbesluit vastleggen.","tekst_036":"Proceseigenaar","tekst_037":"Kansenscan","tekst_038":"Je weet dat werk beter kan, maar nog niet waar je verantwoord begint.","tekst_039":"Prioriteit, 90-dagenroute en één kleine werkende AI-oplossing.","tekst_040":"€ 1.250","tekst_041":"Vaste eerste stap","tekst_042":"Implementatiesprint","tekst_043":"De prioriteit is duidelijk en moet werkend en overdraagbaar worden.","tekst_044":"Maximaal twee samenhangende AI-workflows, getest met medewerkers.","tekst_045":"€ 7.500","tekst_046":"Gericht vervolg","tekst_047":"Groeipartnerschap","tekst_048":"De werkwijze moet blijven werken en gecontroleerd verbeteren.","tekst_049":"Borging, optimalisatie en nieuwe AI-kansen binnen vaste capaciteit.","tekst_050":"Vanaf € 2.250 p/m","tekst_051":"Minimaal zes maanden","tekst_052":"Set In","tekst_053":"Van zichtbare kansen naar een werkende AI-workflow.","tekst_054":"AI-kansen waren zichtbaar, maar moesten worden vertaald naar een werkende workflow en gerichte uitvoering.","tekst_055":"Een werksessie, eerste AI-workflow en marketingplan vormden de basis voor tijdelijke aansturing en overdracht.","tekst_056":"De eerste AI-workflow is gerealiseerd.","tekst_057":"Nulmeting en vervolgmeting zijn nog niet afgerond. Er wordt geen effectcijfer geclaimd.","tekst_058":"Nankaro","tekst_059":"Productontwikkeling en procesverbetering binnen voetbalclubs.","tekst_060":"Trainers besteedden veel tijd aan opstellingen, trainingsvoorbereiding en het bijhouden van spelersontwikkeling.","tekst_061":"Een AI-ondersteunde toepassing verbond planning, communicatie en voortgang rond het team.","tekst_062":"Tot 80 procent tijdwinst binnen opstellingen, trainingsvoorbereiding en spelersontwikkeling.","tekst_063":"Gemeten binnen de genoemde werkzaamheden en productcontext.","tekst_064":"Cameranu","tekst_065":"Dagelijkse marktinformatie voor beleids- en salesbeslissingen.","tekst_066":"Beleids- en salesbeslissers moesten marktinformatie verzamelen voordat zij konden handelen.","tekst_067":"Een AI-workflow analyseerde marktontwikkelingen en maakte de samenvatting dagelijks beschikbaar.","tekst_068":"Sneller beschikbare relevante informatie voor dagelijkse beleids- en salesbeslissingen.","tekst_069":"Geen publiek tijdscijfer. De uitkomst wordt daarom kwalitatief beschreven.","tekst_070":"A.Vogel","tekst_071":"Hergebruik van website-inhoud in e-mailmarketing.","tekst_072":"Het samenstellen van nieuwsbrieven vroeg veel handmatige voorbereiding.","tekst_073":"Een AI-workflow maakte website-inhoud geschikt voor hergebruik in e-mailmarketing.","tekst_074":"Circa 70 procent tijdwinst bij nieuwsbriefproductie.","tekst_075":"Binnen de toegepaste werkwijze voor het samenstellen van nieuwsbrieven.","tekst_076":"Moeten we al weten welke oplossing we nodig hebben?","tekst_077":"Nee. De scan begint bij het bedrijfsdoel en het huidige werk. Pas daarna wordt bepaald welke AI-oplossing of workflow past.","tekst_078":"Wat is een kleine werkende AI-oplossing?","tekst_079":"Een afgebakende AI-oplossing die een medewerker met een representatief voorbeeld kan gebruiken en testen. Zo wordt de waarde zichtbaar zonder het hele proces ineens te vervangen.","tekst_080":"Hoeveel tijd vraagt de scan van onze medewerkers?","tekst_081":"De vaste kern is een voorbereidingsvragenlijst, een werksessie van maximaal 90 minuten, drie representatieve voorbeelden en een korte gebruikstest. Er worden maximaal drie sleutelpersonen betrokken.","tekst_082":"Wat gebeurt er met gevoelige gegevens?","tekst_083":"Setpiece vraagt alleen wat noodzakelijk is. Waar mogelijk werken we met veilige testgegevens of geminimaliseerde voorbeelden. Zonder duidelijke rollen, grondslag of beveiliging stopt de uitvoering.","tekst_084":"Zijn we na de scan verplicht om verder te gaan?","tekst_085":"Nee. De kansenscan is een zelfstandige dienst. Het advies kan zijn om te stoppen, zelf verder te gaan, een implementatiesprint te starten of eerst een aparte verkenning te doen.","footer_tekst_001":"Setpiece","footer_tekst_002":"AI Consultancy voor werk dat eenvoudiger, sneller en consistenter kan. De kansenscan is de vaste eerste stap.","footer_link_003":"/contact","footer_tekst_004":"Contact","footer_tekst_005":"Privacy","footer_tekst_006":"Cookies","footer_tekst_007":"Setpiece · Almere","footer_link_008":"mailto:hallo@setpiece.nl","footer_tekst_009":"hallo@setpiece.nl","footer_link_010":"https://www.linkedin.com/company/setpiece-nl/","footer_tekst_011":"LinkedIn","footer_tekst_012":"© 2026 Setpiece","footer_tekst_013":"KVK 99116111","footer_tekst_014":"Gegevens uit een aanvraag worden alleen gebruikt om die aanvraag te beoordelen.","cta_title":"Weet je dat werk beter kan, maar nog niet waar je begint?","cta_body":"In maximaal 30 minuten verkennen we het werkprobleem, eigenaarschap en de voorwaarden. De volledige diagnose blijft onderdeel van de betaalde scan.","cta_label":"Bespreek de kansenscan","link_cta":"/contact"}'::jsonb,'{"link_001":"link","tekst_002":"text","link_003":"link","tekst_004":"text","link_005":"link","tekst_006":"text","link_007":"link","tekst_008":"text","tekst_009":"text","tekst_010":"text","tekst_011":"text","tekst_012":"text","tekst_013":"text","tekst_014":"text","tekst_015":"text","tekst_016":"text","tekst_017":"text","tekst_018":"text","tekst_019":"text","tekst_020":"text","tekst_021":"text","tekst_022":"text","tekst_023":"text","tekst_024":"text","tekst_025":"text","tekst_026":"text","tekst_027":"text","tekst_028":"text","tekst_029":"text","tekst_030":"text","tekst_031":"text","tekst_032":"text","tekst_033":"text","tekst_034":"text","tekst_035":"text","tekst_036":"text","tekst_037":"text","tekst_038":"text","tekst_039":"text","tekst_040":"text","tekst_041":"text","tekst_042":"text","tekst_043":"text","tekst_044":"text","tekst_045":"text","tekst_046":"text","tekst_047":"text","tekst_048":"text","tekst_049":"text","tekst_050":"text","tekst_051":"text","tekst_052":"text","tekst_053":"text","tekst_054":"text","tekst_055":"text","tekst_056":"text","tekst_057":"text","tekst_058":"text","tekst_059":"text","tekst_060":"text","tekst_061":"text","tekst_062":"text","tekst_063":"text","tekst_064":"text","tekst_065":"text","tekst_066":"text","tekst_067":"text","tekst_068":"text","tekst_069":"text",