insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('home','675024a7-62f2-4eac-ba25-9718bb362e74','{"tekst_001":"Medewerkers verzamelen dezelfde informatie uit meerdere systemen.","tekst_002":"Offertes, rapportages of communicatie blijven te lang liggen.","tekst_003":"Kwaliteit hangt sterk af van één ervaren collega.","tekst_004":"Losse AI-experimenten worden geen vaste werkwijze.","tekst_005":"De directie ziet mogelijkheden, maar mist een verantwoorde eerste keuze.","tekst_006":"Er is een herkenbaar terugkerend werkprobleem.","tekst_007":"Een beslisser en proceseigenaar zijn betrokken.","tekst_008":"Medewerkers krijgen tijd voor de werksessie en test.","tekst_009":"Veilige voorbeelden of testgegevens zijn beschikbaar.","tekst_010":"Er is budget voor een mogelijke vervolgstap.","tekst_011":"De organisatie zoekt alleen vrijblijvende ideeën.","tekst_012":"Er wordt geen eigenaar aangewezen.","tekst_013":"Er is geen tijd voor testen en invoering.","tekst_014":"AI Consultancy voor B2B-dienstverleners met 15 tot 75 medewerkers","kop_015":"Maak dagelijks werk","tekst_016":"eenvoudiger en beter met AI.","tekst_017":"Setpiece onderzoekt waar terugkerend werk vastloopt, bouwt een passende AI-oplossing of workflow en maakt die samen met medewerkers werkend en overdraagbaar.","link_018":"/werkwijze","tekst_019":"Zie hoe het werkspoor loopt","tekst_020":"Investering","tekst_021":"€ 1.250 excl. btw","tekst_022":"Na de werksessie","tekst_023":"5 werkdagen","tekst_024":"Richting","tekst_025":"90-dagenroute","tekst_026":"Eerste bewijs","tekst_027":"1 werkende AI-oplossing","link_028":"/contact","tekst_029":"Bespreek de kansenscan","tekst_030":"Resultaten uit dagelijks werk","kop_031":"Bewijs vóór belofte.","link_032":"/praktijkvoorbeelden","tekst_033":"Bekijk de volledige context","tekst_034":"Waar werk dagelijks lekt","kop_035":"Geen groot systeemprobleem. Wel iedere week verlies.","tekst_036":"AI Consultancy in het echte werk.","kop_037":"AI begint bij het proces.","tekst_038":"Eerst begrijpen wat mensen doen en waar het stokt. Dan de juiste AI-oplossing bouwen, testen en overdragen aan de mensen die ermee werken.","tekst_039":"Vier professionals bespreken een werkproces terwijl Setpiece luistert","tekst_040":"Twee professionals vergelijken processtappen op papier","tekst_041":"De beheerste eerste stap","kop_042":"Begin met één onderbouwde keuze.","tekst_043":"De kansenscan onderzoekt maximaal drie kernprocessen. Binnen vijf werkdagen na de werksessie ontvang je een prioriteit, een route voor 90 dagen en één kleine werkende AI-oplossing.","link_044":"/contact","tekst_045":"Bespreek de kansenscan","link_046":"/kansenscan","tekst_047":"Bekijk scope en voorwaarden","tekst_048":"Werkgebied","tekst_049":"Maximaal drie kernprocessen","tekst_050":"Werksessie","tekst_051":"Maximaal 90 minuten","tekst_052":"Vervolg","tekst_053":"Stoppen, zelf uitvoeren of gericht verder","tekst_054":"Verrekening","tekst_055":"€ 750 bij een sprintstart binnen 30 dagen","tekst_056":"Van kans naar dagelijks gebruik","kop_057":"Iedere halte eindigt met eigenaarschap.","tekst_058":"Eigenaar: ","tekst_059":"Drie diensten, één lijn","kop_060":"Je koopt alleen de volgende logische stap.","tekst_061":"Alle bedragen zijn exclusief btw. De kansenscan is zelfstandig en verplicht niet tot vervolg.","tekst_062":"Verantwoordelijkheid blijft zichtbaar","kop_063":"Eén aanspreekpunt van diagnose tot overdracht.","tekst_064":"Setpiece is opgericht door Nathan Sudmeier. Vanuit ervaring met marketing, communicatie, strategie en productontwikkeling weet hij waar plannen in de dagelijkse praktijk vastlopen.","tekst_065":"Nathan blijft verantwoordelijk voor diagnose, klantrelatie, implementatieregie en kwaliteit. Specialisten worden alleen betrokken wanneer de opdracht dat aantoonbaar vraagt.","link_066":"/over","tekst_067":"Lees waarom Setpiece bestaat","tekst_068":"Goede afbakening voorkomt een verkeerd project","kop_069":"Past de kansenscan bij jouw organisatie?","kop_070":"De scan past wanneer","kop_071":"De scan past niet wanneer","tekst_072":"Veelgestelde vragen","kop_073":"Duidelijk vóór de werksessie.","seo_title":"AI Consultancy voor beter dagelijks werk","seo_description":"Setpiece is een AI Consultancy voor B2B-dienstverleners. We bouwen AI-oplossingen en workflows die terugkerend werk eenvoudiger, sneller en consistenter maken."}'::jsonb,'{"tekst_001":"text","tekst_002":"text","tekst_003":"text","tekst_004":"text","tekst_005":"text","tekst_006":"text","tekst_007":"text","tekst_008":"text","tekst_009":"text","tekst_010":"text","tekst_011":"text","tekst_012":"text","tekst_013":"text","tekst_014":"text","kop_015":"text","tekst_016":"text","tekst_017":"textarea","link_018":"link","tekst_019":"text","tekst_020":"text","tekst_021":"text","tekst_022":"text","tekst_023":"text","tekst_024":"text","tekst_025":"text","tekst_026":"text","tekst_027":"text","link_028":"link","tekst_029":"text","tekst_030":"text","kop_031":"text","link_032":"link","tekst_033":"text","tekst_034":"text","kop_035":"text","tekst_036":"text","kop_037":"text","tekst_038":"textarea","tekst_039":"text","tekst_040":"text","tekst_041":"text","kop_042":"text","tekst_043":"textarea","link_044":"link","tekst_045":"text","link_046":"link","tekst_047":"text","tekst_048":"text","tekst_049":"text","tekst_050":"text","tekst_051":"text","tekst_052":"text","tekst_053":"text","tekst_054":"text","tekst_055":"text","tekst_056":"text","kop_057":"text","tekst_058":"text","tekst_059":"text","kop_060":"text","tekst_061":"text","tekst_062":"text","kop_063":"text","tekst_064":"textarea","tekst_065":"textarea","link_066":"link","tekst_067":"text","tekst_068":"text","kop_069":"text","kop_070":"text","kop_071":"text","tekst_072":"text","kop_073":"text","seo_title":"text","seo_description":"textarea"}'::jsonb);
