insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('kansenscan','675024a7-62f2-4eac-ba25-9718bb362e74','{"tekst_001":"Voorbereidingsvragenlijst.","tekst_002":"Werksessie van maximaal 90 minuten.","tekst_003":"Analyse van maximaal drie kernprocessen.","tekst_004":"Beoordeling op tijd, kwaliteit, omzet, risico en uitvoerbaarheid.","tekst_005":"Compact AI-kansenrapport.","tekst_006":"Route voor de eerste 90 dagen.","tekst_007":"Eén kleine werkende AI-oplossing binnen afgesproken grenzen.","tekst_008":"Besluitgesprek en duidelijk vervolgadvies.","tekst_009":"Eén beslisser en één proceseigenaar.","tekst_010":"Maximaal drie betrokken sleutelpersonen.","tekst_011":"Drie representatieve voorbeelden van terugkerend werk.","tekst_012":"Beschikbare tijd voor werksessie en test.","tekst_013":"Veilige testgegevens of geminimaliseerde voorbeelden.","tekst_014":"Openheid over systemen, uitzonderingen en risico''s.","tekst_015":"Voorbereiden","tekst_016":"Doel, deelnemers, voorbeelden en nulmeting bevestigen.","tekst_017":"Werksessie","tekst_018":"Het huidige proces, verlies, uitzonderingen en gewenste resultaat begrijpen.","tekst_019":"Beoordelen","tekst_020":"Maximaal drie processen vergelijken op waarde, haalbaarheid en risico.","tekst_021":"Verbeteren","tekst_022":"Eén kleine AI-oplossing werkend maken en met een gebruiker testen.","tekst_023":"Besluiten","tekst_024":"Kiezen voor stoppen, zelf uitvoeren, sprint of aparte verkenning.","tekst_025":"Juridische beoordeling.","tekst_026":"Uitgebreide gegevenskoppelingen of migraties.","tekst_027":"Volledige maatwerksoftware.","tekst_028":"Meerdere afdelingen zonder aparte afbakening.","tekst_029":"Onbeperkte wijzigingen.","tekst_030":"Een volledige diagnose in het gratis kennismakingsgesprek.","tekst_031":"Kansenscan","kop_032":"Binnen vijf werkdagen weten waar AI verantwoord verschil kan maken.","tekst_033":"Na de werksessie ontvang je een onderbouwde prioriteit voor AI, een eerste werkende oplossing en een route voor 90 dagen.","tekst_034":"Vaste investering","tekst_035":"€ 1.250","tekst_036":"exclusief btw","tekst_037":"Oplevering binnen vijf werkdagen na de werksessie.","link_038":"/contact","tekst_039":"Bespreek de kansenscan","tekst_040":"Duidelijke oplevering","kop_041":"Wat je ontvangt","tekst_042":"Vaste eigen bijdrage","kop_043":"Wat Setpiece van jou vraagt","tekst_044":"De kansenscan aan tafel","kop_045":"Drie processen. Eén onderbouwde AI-kans.","tekst_046":"Samen leggen we terugkerend werk naast elkaar. We vergelijken waarde, uitvoerbaarheid en risico voordat er een AI-oplossing wordt gekozen.","tekst_047":"Drie professionals vergelijken werkprocessen tijdens een kansenscan","tekst_048":"Van voorbereiding tot besluit","kop_049":"Zo verloopt de scan.","tekst_050":"Duidelijke grenzen","kop_051":"Niet inbegrepen","tekst_052":"Een kleine scope houdt de scan snel, eerlijk en betaalbaar. Groter werk krijgt eerst een aparte afbakening.","tekst_053":"Prijs en vervolg","kop_054":"Een zelfstandige eerste stap.","tekst_055":"Investering","tekst_056":"€ 1.250 exclusief btw","tekst_057":"Betaling","tekst_058":"50% bij opdracht, 50% bij oplevering","tekst_059":"Geldigheid","tekst_060":"Een voorstel is veertien dagen geldig","tekst_061":"Verrekening","tekst_062":"€ 750 bij een sprintstart binnen 30 dagen","tekst_063":"Vervolg","tekst_064":"De scan verplicht niet tot een volgende opdracht","tekst_065":"Veelgestelde vragen","kop_066":"Voorwaarden zonder kleine lettertjes.","kop_067":"Eerst bepalen of de scan past.","tekst_068":"Het kennismakingsgesprek duurt maximaal 30 minuten. We verkennen het werkprobleem en controleren de voorwaarden. De diagnose begint na opdracht.","seo_title":"AI-kansenscan voor betere werkprocessen","seo_description":"Binnen vijf werkdagen een onderbouwde AI-kans, een eerste werkende oplossing en een route voor 90 dagen."}'::jsonb,'{"tekst_001":"text","tekst_002":"text","tekst_003":"text","tekst_004":"text","tekst_005":"text","tekst_006":"text","tekst_007":"text","tekst_008":"text","tekst_009":"text","tekst_010":"text","tekst_011":"text","tekst_012":"text","tekst_013":"text","tekst_014":"text","tekst_015":"text","tekst_016":"text","tekst_017":"text","tekst_018":"text","tekst_019":"text","tekst_020":"text","tekst_021":"text","tekst_022":"text","tekst_023":"text","tekst_024":"text","tekst_025":"text","tekst_026":"text","tekst_027":"text","tekst_028":"text","tekst_029":"text","tekst_030":"text","tekst_031":"text","kop_032":"text","tekst_033":"textarea","tekst_034":"text","tekst_035":"text","tekst_036":"text","tekst_037":"text","link_038":"link","tekst_039":"text","tekst_040":"text","kop_041":"text","tekst_042":"text","kop_043":"text","tekst_044":"text","kop_045":"text","tekst_046":"textarea","tekst_047":"text","tekst_048":"text","kop_049":"text","tekst_050":"text","kop_051":"text","tekst_052":"text","tekst_053":"text","kop_054":"text","tekst_055":"text","tekst_056":"text","tekst_057":"text","tekst_058":"text","tekst_059":"text","tekst_060":"text","tekst_061":"text","tekst_062":"text","tekst_063":"text","tekst_064":"text","tekst_065":"text","kop_066":"text","kop_067":"text","tekst_068":"textarea","seo_title":"text","seo_description":"textarea"}'::jsonb);
