insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('werkwijze','675024a7-62f2-4eac-ba25-9718bb362e74','{"tekst_001":"AI volgt het bedrijfsdoel en het werkproces.","tekst_002":"Iedere opdracht heeft een proceseigenaar.","tekst_003":"Medewerkers worden betrokken bij ontwerp en test.","tekst_004":"Gevoelige beslissingen blijven onder menselijk oordeel.","tekst_005":"Resultaat krijgt een nulmeting en eerste effectmeting.","tekst_006":"De klant kan na overdracht zelfstandig verder.","tekst_007":"Begrijpen","tekst_008":"De medewerker legt het echte werk uit.","tekst_009":"Processtappen, uitzonderingen en terugkerend verlies worden zichtbaar voordat er iets wordt gebouwd.","tekst_010":"Een medewerker legt een werkproces uit terwijl Setpiece luistert en aantekeningen maakt","tekst_011":"Testen","tekst_012":"De medewerker bestuurt de test.","tekst_013":"De AI-oplossing wordt gebruikt in een echte taak. Setpiece observeert, meet en stelt gericht bij.","tekst_014":"Een medewerker test een AI-oplossing op een laptop terwijl Setpiece meekijkt","tekst_015":"Overdragen","tekst_016":"De eigenaar kan zelfstandig verder.","tekst_017":"Werkwijze, controlepunten en verantwoordelijkheden worden aan de organisatie overgedragen.","tekst_018":"Een medewerker draagt een nieuwe werkwijze over aan een manager","tekst_019":"Beslisser","tekst_020":"Bevestigt bedrijfsdoel, budget en vervolgbesluit.","tekst_021":"Proceseigenaar","tekst_022":"Bewaakt inhoud, uitzonderingen en ingebruikname.","tekst_023":"Medewerker","tekst_024":"Test de werkwijze in een echte taak.","tekst_025":"Setpiece","tekst_026":"Draagt diagnose, ontwerp, regie, documentatie en kwaliteitscontrole.","tekst_027":"Specialist","tekst_028":"Wordt alleen betrokken bij aantoonbare technische, juridische of beveiligingsbehoefte.","tekst_029":"De beginsituatie en het gewenste resultaat.","tekst_030":"De gebruikte meetmethode.","tekst_031":"Uitzonderingen en controlepunten.","tekst_032":"Wie beslist en wie uitvoert.","tekst_033":"Wat de klant na overdracht zelfstandig beheert.","tekst_034":"Wanneer stoppen, verbeteren of uitbreiden wordt besloten.","tekst_035":"Werkwijze","kop_036":"AI telt pas wanneer mensen ermee werken.","tekst_037":"Setpiece verbindt bedrijfsdoel, dagelijkse workflow, passende AI-oplossing, test en overdracht in één beheersbare route.","tekst_038":"Principes","kop_039":"Wat tijdens iedere opdracht overeind blijft.","tekst_040":"Het werkspoor","kop_041":"Van frictie naar eigenaarschap.","tekst_042":"Eigenaar: ","tekst_043":"Van analyse naar dagelijks gebruik","kop_044":"AI-oplossingen ontstaan midden in het werk.","tekst_045":"Drie diensten, één route","kop_046":"Ieder onderdeel eindigt met een besluit.","tekst_047":"Rollen en eigenaarschap","kop_048":"De klant weet altijd wie beslist en wie uitvoert.","tekst_049":"Meten en overdragen","kop_050":"Resultaat blijft controleerbaar.","tekst_051":"Iedere verbetering legt vast wat werkte, wie verantwoordelijk is en wat de organisatie zelfstandig beheert.","tekst_052":"De AI-oplossing wordt pas gekozen nadat het werk duidelijk is.","kop_053":"AI zonder eigenaar en werkwijze is geen oplevering.","kop_054":"Begin met het werkprobleem. Niet met een losse AI-tool.","seo_title":"AI Consultancy: van werkprobleem naar workflow","seo_description":"Setpiece verbindt bedrijfsdoel, dagelijkse workflow, passende AI-oplossing, test, meting en overdracht."}'::jsonb,'{"tekst_001":"text","tekst_002":"text","tekst_003":"text","tekst_004":"text","tekst_005":"text","tekst_006":"text","tekst_007":"text","tekst_008":"text","tekst_009":"text","tekst_010":"text","tekst_011":"text","tekst_012":"text","tekst_013":"text","tekst_014":"text","tekst_015":"text","tekst_016":"text","tekst_017":"text","tekst_018":"text","tekst_019":"text","tekst_020":"text","tekst_021":"text","tekst_022":"text","tekst_023":"text","tekst_024":"text","tekst_025":"text","tekst_026":"text","tekst_027":"text","tekst_028":"text","tekst_029":"text","tekst_030":"t