insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('praktijkvoorbeelden','675024a7-62f2-4eac-ba25-9718bb362e74','{"tekst_001":"Praktijkvoorbeelden","kop_002":"Wat veranderde er in het dagelijkse werk?","tekst_003":"Vier voorbeelden laten zien hoe AI-oplossingen minder handwerk, snellere informatie en een vaste werkwijze mogelijk maken.","tekst_004":"Werkspoor in de praktijk","kop_005":"Beginsituatie","kop_006":"Wat veranderde","kop_007":"Resultaat","tekst_008":"Meetcontext","tekst_009":"Ieder voorbeeld volgt hetzelfde format: beginsituatie, ingreep, resultaat en context. Cijfers worden alleen gepubliceerd wanneer de meetmethode en gebruikscontext zijn vastgelegd.","kop_010":"Welk terugkerend werk verdient als eerste aandacht?","seo_title":"AI-oplossingen in dagelijks werk","seo_description":"Vier praktijkvoorbeelden laten zien hoe AI-oplossingen minder handwerk, snellere informatie en een vaste werkwijze mogelijk maken."}'::jsonb,'{"tekst_001":"text","kop_002":"text","tekst_003":"textarea","tekst_004":"text","kop_005":"text","kop_006":"text","kop_007":"text","tekst_008":"text","tekst_009":"textarea","kop_010":"text","seo_title":"text","seo_description":"textarea"}'::jsonb);
