insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('over','675024a7-62f2-4eac-ba25-9718bb362e74','{"tekst_001":"Nankaro","tekst_002":"Productontwikkeling en procesverbetering binnen voetbalclubs.","tekst_003":"Cameranu","tekst_004":"Analyses, communicatie, financiële rapportages en dagelijkse besluitvorming.","tekst_005":"A.Vogel","tekst_006":"E-mailmarketing en hergebruik van website-inhoud.","tekst_007":"Set In","tekst_008":"Werksessie, workflow, marketingplan en tijdelijke implementatieregie.","tekst_009":"Over Setpiece","kop_010":"Praktische ervaring aan de directietafel en op de werkvloer.","tekst_011":"Nathan Sudmeier verbindt AI Consultancy met strategie, procesverbetering, productontwikkeling en dagelijkse uitvoering.","tekst_012":"Nathan Sudmeier, oprichter van Setpiece","tekst_013":"Waarom Setpiece bestaat","kop_014":"Geen losse presentatie. Een werkwijze die blijft.","tekst_015":"Veel organisaties zien kansen met AI, maar hebben weinig aan een losse presentatie, tool of verzameling prompts. Zij hebben iemand nodig die het werk begrijpt, een proces afbakent en een bruikbare AI-oplossing bouwt die medewerkers zelfstandig kunnen gebruiken.","tekst_016":"Setpiece is opgericht om die rol te vervullen. Het is een AI Consultancy die bedrijfsdoel, uitvoering en borging bij elkaar brengt, zonder één techniek tot vertrekpunt te maken.","tekst_017":"Ervaring als bewijs","kop_018":"Werk dat lijkt op het werk van de klant.","link_019":"/praktijkvoorbeelden","tekst_020":"Bekijk de praktijkvoorbeelden","kop_021":"Verantwoordelijkheid blijft bij één persoon.","tekst_022":"Nathan houdt strategie, diagnose, klantrelatie, implementatieregie en kwaliteitscontrole bij zichzelf. Specialistisch werk wordt alleen toegevoegd wanneer veiligheid, kwaliteit of capaciteit dat noodzakelijk maakt. De klant weet altijd wie beslist en wie verantwoordelijk is.","tekst_023":"Werkgebied","kop_024":"Regionaal dichtbij. Landelijk wanneer het past.","tekst_025":"Friesland, Groningen, Drenthe en Flevoland vormen de regionale basis. Opdrachten daarbuiten passen wanneer het bedrijfsprobleem, de introductie of de herhaalbaarheid sterk aansluit.","kop_026":"Een concreet werkprobleem om te bespreken?","seo_title":"AI-consultant voor strategie en uitvoering","seo_description":"Nathan Sudmeier verbindt AI Consultancy met strategie, procesverbetering, productontwikkeling en dagelijkse uitvoering."}'::jsonb,'{"tekst_001":"text","tekst_002":"text","tekst_003":"text","tekst_004":"text","tekst_005":"text","tekst_006":"text","tekst_007":"text","tekst_008":"text","tekst_009":"text","kop_010":"text","tekst_011":"text","tekst_012":"text","tekst_013":"text","kop_014":"text","tekst_015":"textarea","tekst_016":"textarea","tekst_017":"text","kop_018":"text","link_019":"link","tekst_020":"text","kop_021":"text","tekst_022":"textarea","tekst_023":"text","kop_024":"text","tekst_025":"textarea","kop_026":"text","seo_title":"text","seo_description":"textarea"}'::jsonb);
