insert into public.sp_cms_documents(slug,owner_id,draft,field_schema) values('contact','675024a7-62f2-4eac-ba25-9718bb362e74','{"tekst_001":"Setpiece beoordeelt of het probleem en de organisatie bij de scan passen.","tekst_002":"Nathan reageert binnen twee werkdagen.","tekst_003":"Bij een mogelijke match volgt een gesprek van maximaal 30 minuten.","tekst_004":"Daarna ontvang je wel of geen voorstel voor de kansenscan.","tekst_005":"Contact","kop_006":"Bespreek of de kansenscan past.","tekst_007":"In maximaal 30 minuten verkennen we het werkprobleem, eigenaarschap en de mogelijke AI-kans. De volledige diagnose is betaald.","kop_008":"Wat gebeurt er na je aanvraag?","tekst_009":"Liever direct mailen?","link_010":"mailto:hallo@setpiece.nl","tekst_011":"hallo@setpiece.nl","seo_title":"Bespreek de AI-kansenscan","seo_description":"Verken in maximaal 30 minuten het werkprobleem, de mogelijke AI-kans en de voorwaarden van de kansenscan."}'::jsonb,'{"tekst_001":"text","tekst_002":"text","tekst_003":"text","tekst_004":"text","tekst_005":"text","kop_006":"text","tekst_007":"textarea","kop_008":"text","tekst_009":"text","link_010":"link","tekst_011":"text","seo_title":"text","seo_description":"textarea"}'::jsonb);
